cd /tmp && python3 << 'EOF'
exec(open('/tmp/load.py').read())
pats={p['id']:p for p in R['Patient']}
by_mrn_dob={}
for p in R['Patient']:
    by_mrn_dob[(p['identifier'][0]['value'], p['birthDate'])]=p['id']
spec={s['id']:s for s in R['Specimen']}
acc_basic=collections.defaultdict(list)
for b in R['Basic']: acc_basic[ext(b,'accession')].append(b)
prob=[]
for o in R['Observation']:
    cp=subj(o)
    sp=spec.get(o.get('specimen',{}).get('reference','').split('/')[-1])
    acc=(o.get('identifier') or [{}])[0].get('value')
    bs=acc_basic.get(acc,[])
    s_id=(ext(sp,'label-mrn'), str(ext(sp,'label-dob'))) if sp else None
    b_ids=[(ext(b,'patient-mrn'), str(ext(b,'patient-dob'))) for b in bs]
    chart=(pats[cp]['identifier'][0]['value'], pats[cp]['birthDate'])
    issues=[]
    if s_id!=chart: issues.append('spec_label_mismatch')
    for bi in b_ids:
        if bi!=chart: issues.append('acc_mismatch')
    if len(bs)!=1: issues.append(f'nbasic={len(bs)}')
    if sp and subj(sp)!=cp: issues.append('spec_subject_diff')
    if sp and sp.get('accessionIdentifier',{}).get('value')!=acc: issues.append('acc_num_diff')
    if issues:
        prob.append((cp,o['id'],o['code']['text'],o.get('effectiveDateTime','')[:10],issues,s_id,b_ids,chart, by_mrn_dob.get(s_id), [by_mrn_dob.get(x) for x in b_ids]))
print(len(prob))
for x in prob: print(x)
